typedef unsigned int u_int;

struct nglQuad
{
    char data[0x8c];
};

extern "C" void adjustCoords(float &, float &)
    __asm__("adjustCoords__H1Zf_RX01T0_v");
extern "C" void nglSetQuadVPos(nglQuad *, int, float, float)
    __asm__("nglSetQuadVPos__FP7nglQuadiff");
extern "C" void nglSetQuadColor(nglQuad *, u_int)
    __asm__("nglSetQuadColor__FP7nglQuadUi");
extern "C" void nglSetQuadZ(nglQuad *, float)
    __asm__("nglSetQuadZ__FP7nglQuadf");

class PanelQuad4
{
    char panel_quad_prefix[0x1c];
    nglQuad quad;
    char panel_quad_tail[0xec];
    float width;
    float height;
    char panel_quad_end[0xb0];
    float x[4];
    float y[4];
    float u[4];
    float v[4];
    float r, g, b, a;
    float z;

public:
    virtual void Init(float xa, float xb, float xc, float xd,
                      float ya, float yb, float yc, float yd,
                      float r1, float g1, float b1, float a1, float z1);
};

#define FTOI(x) ((int)(x))
#define NGL_RGBA32(r, g, b, a) \
    (((int)((r) + 1) >> 1) | (((int)((g) + 1) >> 1) << 8) | \
     (((int)((b) + 1) >> 1) << 16) | (((int)((a) + 1) >> 1) << 24))

void PanelQuad4::Init(float xa, float xb, float xc, float xd,
                      float ya, float yb, float yc, float yd,
                      float r1, float g1, float b1, float a1, float z1)
{
    r = r1; g = g1; b = b1; a = a1;
    z = z1;
    x[0] = xa; x[1] = xb; x[2] = xc; x[3] = xd;
    y[0] = ya; y[1] = yb; y[2] = yc; y[3] = yd;
    for(int i=0; i<4; i++)
    {
        adjustCoords(x[i], y[i]);
        nglSetQuadVPos(&quad, i, x[i], y[i]);
    }
    nglSetQuadColor(&quad, NGL_RGBA32(FTOI(r*255.0f), FTOI(g*255.0f), FTOI(b*255.0f), FTOI(a*255.0f)));

    nglSetQuadZ(&quad, z);

    width = x[1]-x[0];
    height = y[2]-y[0];
}
